from pathlib import Path
import shutil,hashlib,json
w=Path(__file__).parent.resolve();out=w.parents[1]/'outputs/Project-Syndicate-Standalone-v0.3.40';out.mkdir(exist_ok=True)
assert (w/'exercise-final.verified.txt').exists()
assert (w/'verified-final.verified.txt').exists()
exe=out/'Project-Syndicate-v0.3.40.exe';shutil.copy2(w/'publish/Project-Syndicate-Standalone.exe',exe)
digest=hashlib.sha256(exe.read_bytes()).hexdigest();(out/(exe.name+'.sha256')).write_text(digest+'  '+exe.name+'\n')
shutil.copy2(w/'component-manifest.json',out/'component-manifest.json')
(out/'READ ME.txt').write_text('Syndicate v0.3.40 standalone - Seasons 2, 3, 4 and 5\n\nClose older Syndicate launchers and Fortnite first. Run Project-Syndicate-v0.3.40.exe. Wait for setup, sign in, choose your extracted Fortnite folder, and launch. Fortnite itself is not included.\n\nKeep this EXE: reopen it to launch or restore its program files. No update ZIP or RepairSyndicate.cmd is needed. Automatic update downloads are disabled.\n\nExisting public accounts use Local AppData/SyndicateClassic/UserData. Do not delete that folder. Older accounts still stored inside an old installation should be migrated/backed up before deleting that installation.\n\nThe bundled program archive is encrypted. Runtime files are readable while needed and removed after a clean exit when unlocked. A crash or locked process can leave readable files. This is not protection against a determined reverse engineer.\n\nThis build is unsigned. Antivirus or Windows reputation warnings and individual game/PC issues cannot be ruled out. Do not disable antivirus to run it.\n')
(out/'VALIDATION.txt').write_text('Unpublished public standalone candidate 0.3.40\nPASS launcher build/self-contained .NET files, four launchable seasons (2-5), assembly version0.3.40.\nPASS 22,415 payload files authenticated with AES256-GCM and checked after extraction; ZIP CRC and individual SHA256 manifest.\nPASS no private accounts/configuration, debug symbols or project C++/C# sources in distribution. JavaScript runtime is decrypted during execution.\nPASS encrypted-payload tamper rejection, traversal rejection, exclusive file-lock preflight, damaged program-file restoration, cleanup preserving unrelated user files.\nPASS account migration/journal retention, original retention, reinstall preservation, newest backup recovery, corrupted backup rejection and live-database lock rejection. These are isolated fixtures, not migrations of user databases.\nPASS actual bundled backend S5 tiers, shop rotations, pass exclusions, S4/S5 full passes, packs, challenge gates and persistence; S2-S4 comparison checks.\nNOT TESTED: full Fortnite matches through this new wrapper on each supported season, clean second-PC installation, antivirus acceptance, code-signing reputation. NuGet vulnerability feed unavailable during build.\nNo updater package or upgrade was built: user explicitly requested standalone-only. Existing updater regression suites are not applicable. Existing installations, account stores and public release remain untouched.\n')
(w/'delivery.json').write_text(json.dumps({'exe':str(exe),'sha256':digest,'bytes':exe.stat().st_size},indent=2))
print(json.dumps({'exe':str(exe),'sha256':digest,'megabytes':round(exe.stat().st_size/1048576,1)}))
